# ================================================================
# Test 1: testCreateDiffBlock - Diff 블록 생성
# ================================================================
fn testCreateDiffBlock(): map {
  # Arrange
  let lineType = "added"
  let lineNumber = 1
  let content = "fn hello(): string {"
  let baseLineNum = -1
  let newLineNum = 1

  # Act
