  # Assert
  let passed = true
  let failures = [] as [string]

  if block["type"] != lineType {
    passed = false
    failures = append(failures, "Type mismatch")
  }

  if block["lineNumber"] != lineNumber {
    passed = false
    failures = append(failures, "Line number mismatch")
  }

  if block["content"] != content {
    passed = false
    failures = append(failures, "Content mismatch")
  }

  if block["className"] != "diff-added" {
    passed = false
    failures = append(failures, "CSS class mismatch for added")
  }

  if !contains(block, "html") {
    passed = false
    failures = append(failures, "Missing html field")
  }

  return {
    "testName": "testCreateDiffBlock",
    "passed": passed,
    "failures": failures
  }
}

# ================================================================
# Test 2: testGetClassNameForType - CSS 클래스 매핑
# ================================================================
fn testGetClassNameForType(): map {
  # Arrange
