    { "type": "added", "expectedClass": "diff-added" },
    { "type": "removed", "expectedClass": "diff-removed" },
    { "type": "modified", "expectedClass": "diff-modified" },
    { "type": "unchanged", "expectedClass": "diff-unchanged" }
  ] as [map]

  # Act & Assert
  let passed = true
  let failures = [] as [string]
  let i = 0

  while i < len(testCases) {
    let testCase = testCases[i]
    let className = getClassNameForType(testCase["type"])

    if className != testCase["expectedClass"] {
      passed = false
      failures = append(failures,
        "Type " + testCase["type"] + " should map to " + testCase["expectedClass"]
      )
    }

    i = i + 1
  }

  return {
    "testName": "testGetClassNameForType",
    "passed": passed,
    "totalTests": len(testCases),
    "failures": failures
