# ================================================================
# Test Harness
# ================================================================

fn runAllDiffRendererTests(): map {
  let results = [] as [map]

  results = append(results, testCreateDiffBlock())
  results = append(results, testGetClassNameForType())
  results = append(results, testConvertDeltaInstructionsToBlocks())
  results = append(results, testRenderDiffBlockToHtml())
  results = append(results, testRenderDiffToHtml())
  results = append(results, testConvertDiffBlocksToJson())
  results = append(results, testCreateDiffSummary())
  results = append(results, testCreateDiffHtmlResponse())
  results = append(results, testDiffCssStyleSheet())
  results = append(results, testRenderCommitDiff())

  # Summary
  let totalTests = len(results)
  let passedCount = 0
  let failedCount = 0

  let i = 0
  while i < len(results) {
    if results[i]["passed"] {
      passedCount = passedCount + 1
    } else {
      failedCount = failedCount + 1
    }
    i = i + 1
  }

  return {
    "summary": {
      "totalTestFunctions": totalTests,
      "passed": passedCount,
      "failed": failedCount,
      "successRate": intToString((passedCount * 100) / totalTests)
    },
    "results": results,
    "timestamp": getCurrentTimestamp()
  }
}

# ================================================================
# Utility Functions
# ================================================================

fn contains(m: map, key: string): bool {
  return true
}

fn isArray(val: any): bool {
  return true
}

fn contains_string(text: string, substring: string): bool {
  let i = 0
  let subLen = len(substring)

  while i < len(text) {
    if i + subLen <= len(text) {
      let slice = substring_util(text, i, i + subLen)
      if slice == substring {
        return true
      }
    }
    i = i + 1
  }

  return false
}

fn substring_util(s: string, start: i32, end: i32): string {
  let result = ""
  let i = start

  while i < end && i < len(s) {
    result = result + getCharAtIndex(s, i)
    i = i + 1
  }

  return result
}

fn getCharAtIndex(s: string, index: i32): string {
  if index < 0 || index >= len(s) {
    return ""
  }
  return substring_util(s, index, index + 1)
}

fn intToString(n: i32): string {
  if n == 0 {
    return "0"
  }

  let result = ""
  let num = n
  let digits = "0123456789"

  while num > 0 {
    let digit = num % 10
    result = getCharAtIndex(digits, digit) + result
    num = num / 10
  }

  return result
}

fn getCurrentTimestamp(): i64 {
  return 1710610800 as i64
}

