# ================================================================
# FreeGit 3단계: Commit 객체
# "언제, 누가, 왜"를 기록하는 시간의 체인
# ================================================================

# ================================================================
# Part 1: Commit 객체 정의
# ================================================================

# Commit 생성
fn createCommit(
  treeHash: string,
  parentHash: string,
  author: string,
  message: string
): map {
  # 현재 시간 (타임스탬프)
  let timestamp = getCurrentTimestamp()

  # Commit 데이터 직렬화
  let commitData = serializeCommitData(treeHash, parentHash, author, timestamp, message)

  # 헤더 추가: "commit {size}\x00{data}"
  let header = "commit " + intToString(len(commitData)) + "\x00"
  let fullData = header + commitData

  # 해싱
  let hash = simpleHash(fullData)

  return {
    "type": "commit",
    "treeHash": treeHash,
    "parentHash": parentHash,
    "author": author,
    "timestamp": timestamp,
    "message": message,
    "hash": hash,
    "data": commitData,
    "fullData": fullData
  }
}

# ================================================================
# Part 2: Commit 데이터 직렬화
# ================================================================

# Commit을 저장 가능한 형식으로 변환
fn serializeCommitData(
  treeHash: string,
  parentHash: string,
  author: string,
  timestamp: i64,
  message: string
): string {
  # Git Commit 형식:
  # tree {hash}
  # parent {hash}
  # author {name} {timestamp}
  # committer {name} {timestamp}
  # {message}

  let data = ""

  # 1. Tree 해시
  data = data + "tree " + treeHash + "\n"

  # 2. Parent 해시 (첫 커밋은 생략)
  if parentHash != "" && parentHash != "0000000000000000000000000000000000000000" {
    data = data + "parent " + parentHash + "\n"
  }

  # 3. 작성자
  data = data + "author " + author + " " + int64ToString(timestamp) + "\n"

  # 4. Committer (작성자와 같음)
  data = data + "committer " + author + " " + int64ToString(timestamp) + "\n"

  # 5. 빈 줄
  data = data + "\n"

  # 6. 메시지
  data = data + message

  return data
}

# ================================================================
# Part 3: Commit 저장 및 읽기
# ================================================================

# Commit을 저장소에 저장
fn storeCommit(repoPath: string, commit: map): bool {
  let hash = commit["hash"]
  let fullData = commit["fullData"]

  # 저장 경로: .freegit/objects/xx/yyyyyyyy
  let dirPart = substring(hash, 0, 2)
  let filePart = substring(hash, 2, 40)
  let dirPath = repoPath + "/.freegit/objects/" + dirPart
  let filePath = dirPath + "/" + filePart

  # 디렉토리 생성
  createDirectory(dirPath)

  # 파일 저장
  writeFileContent(filePath, fullData)

  return true
}

# Commit 읽기
fn readCommit(repoPath: string, hash: string): map {
  let dirPart = substring(hash, 0, 2)
  let filePart = substring(hash, 2, 40)
  let filePath = repoPath + "/.freegit/objects/" + dirPart + "/" + filePart

  let fullData = readFileContent(filePath)

  # "commit {size}\x00{data}" 형식에서 데이터만 추출
  let data = parseCommitData(fullData)

  return {
    "type": "commit",
    "hash": hash,
    "data": data,
    "treeHash": data["treeHash"],
    "parentHash": data["parentHash"],
    "author": data["author"],
    "timestamp": data["timestamp"],
    "message": data["message"]
  }
}

# ================================================================
# Part 4: Commit 데이터 파싱
# ================================================================

fn parseCommitData(fullData: string): map {
  # "commit {size}\x00{data}" 형식 파싱
  let nullIndex = findChar(fullData, "\x00")
  if nullIndex < 0 {
    return {}
  }

  let data = substring(fullData, nullIndex + 1, len(fullData))

  # 각 줄 파싱
  let lines = splitByNewline(data)
  let result = {
    "treeHash": "",
    "parentHash": "",
    "author": "",
    "timestamp": 0,
    "message": ""
  }

  let messageStart = -1
  let i = 0

  while i < len(lines) {
    let line = lines[i]

    if line == "" {
      # 빈 줄: 여기부터 메시지 시작
      messageStart = i + 1
      break
    }

    # "key value" 형식 파싱
    let spaceIndex = findChar(line, " ")
    if spaceIndex > 0 {
      let key = substring(line, 0, spaceIndex)
      let value = substring(line, spaceIndex + 1, len(line))

      if key == "tree" {
        result["treeHash"] = value
      } else if key == "parent" {
        result["parentHash"] = value
      } else if key == "author" {
        # "author {name} {timestamp}" 형식
        let parts = splitBySpace(value)
        if len(parts) >= 2 {
          result["author"] = parts[0]
          result["timestamp"] = stringToInt64(parts[1])
        }
      }
    }

    i = i + 1
  }

  # 메시지 추출
  if messageStart >= 0 {
    let messageLines = [] as [string]
    let j = messageStart

    while j < len(lines) {
      messageLines = append(messageLines, lines[j])
      j = j + 1
    }

    result["message"] = joinLines(messageLines)
  }

  return result
}

# 줄로 문자열 분리
fn splitByNewline(s: string): [string] {
  let result = [] as [string]
  let currentLine = ""
  let i = 0

  while i < len(s) {
    let char = getCharAtIndex(s, i)

    if char == "\n" {
      result = append(result, currentLine)
      currentLine = ""
    } else {
      currentLine = currentLine + char
    }

    i = i + 1
  }

  # 마지막 줄
  if len(currentLine) > 0 {
    result = append(result, currentLine)
  }

  return result
}

# 줄들을 다시 연결
fn joinLines(lines: [string]): string {
  let result = ""
  let i = 0

  while i < len(lines) {
    result = result + lines[i]
    if i < (len(lines) - 1) {
      result = result + "\n"
    }
    i = i + 1
  }

  return result
}

# ================================================================
# Part 5: HEAD 관리 (현재 커밋)
# ================================================================

# HEAD 파일에 현재 커밋 해시 저장
fn setHead(repoPath: string, commitHash: string): bool {
  let headPath = repoPath + "/.freegit/HEAD"
  let refPath = repoPath + "/.freegit/refs/heads/main"

  # refs/heads/main에 커밋 해시 저장
  writeFileContent(refPath, commitHash + "\n")

  # HEAD 파일은 refs/heads/main을 가리키도록
  writeFileContent(headPath, "ref: refs/heads/main\n")

  return true
}

# 현재 HEAD 커밋 해시 읽기
fn getHead(repoPath: string): string {
  let refPath = repoPath + "/.freegit/refs/heads/main"
  let content = readFileContent(refPath)

  # 첫 줄이 커밋 해시
  let lines = splitByNewline(content)
  if len(lines) > 0 {
    return lines[0]
  }

  return ""  # 첫 커밋
}

# ================================================================
# Part 6: Commit 히스토리 조회
# ================================================================

# 커밋 로그 출력
fn getCommitHistory(repoPath: string, maxCount: i32): [map] {
  let commits = [] as [map]
  let currentHash = getHead(repoPath)
  let count = 0

  while currentHash != "" && count < maxCount {
    let commit = readCommit(repoPath, currentHash)
    commits = append(commits, commit)

    # 다음 커밋 (parent)
    currentHash = commit["parentHash"]
    count = count + 1
  }

  return commits
}

# ================================================================
# Part 7: 검증
# ================================================================

# Commit 검증
fn verifyCommit(repoPath: string, hash: string): bool {
  let commit = readCommit(repoPath, hash)
  let recalculatedHash = simpleHash(commit["fullData"])

  return recalculatedHash == hash
}

# Commit 체인 검증 (HEAD부터 시작)
fn verifyCommitChain(repoPath: string): bool {
  let currentHash = getHead(repoPath)

  while currentHash != "" {
    # 현재 커밋 검증
    if !verifyCommit(repoPath, currentHash) {
      return false
    }

    # 이전 커밋으로
    let commit = readCommit(repoPath, currentHash)
    currentHash = commit["parentHash"]
  }

  return true
}

# ================================================================
# Part 8: Commit 정보 출력
# ================================================================

fn printCommit(commit: map): any {
  println("commit " + commit["hash"])
  println("Author: " + commit["author"])
  println("Date: " + int64ToString(commit["timestamp"]))
  println("")
  println("  " + commit["message"])
  println("")

  return null
}

fn printCommitLog(commits: [map]): any {
  for commit in commits {
    printCommit(commit)
  }

  return null
}

# ================================================================
# Part 9: 유틸리티
# ================================================================

fn getCurrentTimestamp(): i64 {
  # TODO: FreeLang에서 시스템 시간 호출
  # 현재는 고정값 반환 (테스트용)
  # 실제 구현: os::getTime() 또는 time::now() 호출
  return 1710610800  # 2024-03-16 12:00:00 UTC
}

fn int64ToString(num: i64): string {
  if num == 0 {
    return "0"
  }

  let result = ""
  let n = num
  let digits = "0123456789"

  while n > 0 {
    let digit = (n % 10) as i32
    result = getCharAtIndex(digits, digit) + result
    n = n / 10
  }

  return result
}

fn stringToInt64(s: string): i64 {
  let result = 0 as i64
  let i = 0

  while i < len(s) {
    let char = getCharAtIndex(s, i)

    # 문자를 숫자로 변환 ('0'=48, '1'=49, ..., '9'=57)
    if char == "0" {
      result = result * 10 + 0
    } else if char == "1" {
      result = result * 10 + 1
    } else if char == "2" {
      result = result * 10 + 2
    } else if char == "3" {
      result = result * 10 + 3
    } else if char == "4" {
      result = result * 10 + 4
    } else if char == "5" {
      result = result * 10 + 5
    } else if char == "6" {
      result = result * 10 + 6
    } else if char == "7" {
      result = result * 10 + 7
    } else if char == "8" {
      result = result * 10 + 8
    } else if char == "9" {
      result = result * 10 + 9
    } else {
      # 숫자가 아닌 문자는 무시
      break
    }

    i = i + 1
  }

  return result
}

fn intToString(num: i32): string {
  if num == 0 {
    return "0"
  }

  let result = ""
  let n = num
  let digits = "0123456789"

  while n > 0 {
    let digit = n % 10
    result = getCharAtIndex(digits, digit) + result
    n = n / 10
  }

  return result
}

fn substring(s: string, start: i32, end: i32): string {
  let result = ""
  let i = start

  while i < end && i < len(s) {
    result = result + getCharAtIndex(s, i)
    i = i + 1
  }

  return result
}

fn splitBySpace(s: string): [string] {
  let result = [] as [string]
  let currentWord = ""
  let i = 0

  while i < len(s) {
    let char = getCharAtIndex(s, i)

    if char == " " {
      if len(currentWord) > 0 {
        result = append(result, currentWord)
        currentWord = ""
      }
    } else {
      currentWord = currentWord + char
    }

    i = i + 1
  }

  if len(currentWord) > 0 {
    result = append(result, currentWord)
  }

  return result
}

fn findChar(s: string, char: string): i32 {
  let i = 0
  while i < len(s) {
    if getCharAtIndex(s, i) == char {
      return i
    }
    i = i + 1
  }
  return -1
}

fn getCharAtIndex(s: string, index: i32): string {
  # 특정 인덱스의 문자 추출 (substring 활용)
  if index < 0 || index >= len(s) {
    return ""
  }
  return substring(s, index, index + 1)
}

fn simpleHash(data: string): string {
  # 간단한 해시 함수 (40자리 16진수)
  # TODO: 실제 SHA1 알고리즘으로 교체
  let hash = 0 as i64
  let i = 0

  # 각 문자의 ASCII 값을 곱셈-덧셈으로 해싱
  while i < len(data) {
    let char = getCharAtIndex(data, i)
    let ascii = getCharCode(char)
    hash = (hash * 31 + ascii) % 0x7FFFFFFFFFFFFFFF
    i = i + 1
  }

  # 40자리 16진수로 변환
  return padZeros(toHexString(hash), 40)
}

fn getCharCode(char: string): i64 {
  # 문자의 ASCII 값 추정
  # 정확한 구현은 FreeLang의 문자 관련 함수에 의존
  if len(char) == 0 {
    return 0 as i64
  }

  # 문자별로 ASCII 값 매핑 (간단한 구현)
  # 실제로는 모든 ASCII 문자를 지원해야 함
  if char == " " { return 32 as i64 }
  else if char == "\n" { return 10 as i64 }
  else if char == "\t" { return 9 as i64 }
  else if char == "\x00" { return 0 as i64 }
  else if char == "0" { return 48 as i64 }
  else if char == "1" { return 49 as i64 }
  else if char == "2" { return 50 as i64 }
  else if char == "a" { return 97 as i64 }
  else if char == "b" { return 98 as i64 }
  else if char == "t" { return 116 as i64 }
  else { return 65 as i64 }  # 기본값 'A'
}

fn toHexString(num: i64): string {
  if num == 0 {
    return "0"
  }

  let hex = ""
  let hexChars = "0123456789abcdef"
  let n = num

  while n > 0 {
    let remainder = (n % 16) as i32
    hex = getCharAtIndex(hexChars, remainder) + hex
    n = n / 16
  }

  return hex
}

fn padZeros(s: string, length: i32): string {
  let currentLen = len(s)
  let result = s

  let i = 0
  while i < (length - currentLen) {
    result = "0" + result
    i = i + 1
  }

  return result
}

fn createDirectory(path: string): bool {
  # TODO: FreeLang에서 파일시스템 호출
  # 임시 구현: 항상 성공 반환
  # 실제: fs::mkdir() 또는 os::createDir() 호출
  return true
}

fn writeFileContent(path: string, content: string): bool {
  # TODO: FreeLang에서 파일 쓰기 호출
  # 임시 구현: 항상 성공 반환
  # 실제: fs::write() 또는 io::File::new().write_all() 호출
  return true
}

fn readFileContent(path: string): string {
  # TODO: FreeLang에서 파일 읽기 호출
  # 임시 구현: 빈 문자열 반환
  # 실제: fs::read() 또는 io::File::new().read_to_string() 호출
  return ""
}

fn println(text: string): any {
  # TODO: FreeLang 표준출력 함수 호출
  # 임시 구현: 아무것도 하지 않음
  # 실제: io::println() 또는 print() 호출
  return null
}

