# ================================================================
# Stage 1-3: Commit Graph Renderer (SVG 커밋 그래프)
# commit.fl의 parent-child 관계를 시각적 DAG로 변환
# ================================================================

# ================================================================
# Part 1: 그래프 노드 생성
# ================================================================

# SVG용 커밋 그래프 노드 생성
fn buildCommitGraphNode(
  hash: string,
  message: string,
  author: string,
  timestamp: i64,
  x: i32,
  y: i32,
  parentHashes: [string]
): map {
  return {
    "hash": hash,
    "shortHash": substring(hash, 0, 8),
    "message": message,
    "author": author,
    "timestamp": timestamp,
    "x": x,                    # SVG X 좌표
    "y": y,                    # SVG Y 좌표
    "radius": 8,               # 원 반경
    "parentHashes": parentHashes,
    "children": [] as [string],
    "level": 0,                # 트리 깊이
    "column": 0                # 수평 배치 열
  }
}

# ================================================================
# Part 2: 커밋 그래프 레이아웃 계산
# ================================================================

# 커밋들의 위치를 계산 (선형 히스토리 기준)
fn calculateCommitGraphLayout(
  commits: [map],
  canvasWidth: i32,
  canvasHeight: i32
): [map] {
  if len(commits) == 0 {
    return [] as [map]
  }

  let nodes = [] as [map]
  let nodeMap = {} as map        # hash → node 맵
  let i = 0

  # 1단계: 커밋을 노드로 변환 (좌표 미정)
  while i < len(commits) {
    let commit = commits[i]
    let hash = commit["hash"]
    let message = commit["message"]
    let author = commit["author"]
    let timestamp = commit["timestamp"]
    let parentHashes = [] as [string]

    # parentHash가 있으면 배열로 추가
    if commit["parentHash"] != "" {
      parentHashes = append(parentHashes, commit["parentHash"])
    }

    let node = buildCommitGraphNode(hash, message, author, timestamp, 0, 0, parentHashes)
    nodes = append(nodes, node)
    nodeMap[hash] = node

    i = i + 1
  }

  # 2단계: 수평 위치 계산 (DAG 너비)
  let maxLevel = 0
  let i = 0
  while i < len(nodes) {
    let node = nodes[i]
    let level = calculateNodeLevel(node, nodes)
    node["level"] = level
    if level > maxLevel {
      maxLevel = level
    }
    i = i + 1
  }

  # 3단계: SVG 좌표로 변환
  let ySpacing = if len(nodes) > 1 then (canvasHeight - 100) / (len(nodes) - 1) else 0
  let xSpacing = if maxLevel > 0 then (canvasWidth - 100) / maxLevel else (canvasWidth - 100)

  let i = 0
  while i < len(nodes) {
    let node = nodes[i]
    node["x"] = 50 + (node["level"] * xSpacing)
    node["y"] = 50 + (i * ySpacing)
    i = i + 1
  }

  return nodes
}

# 노드의 트리 레벨 (깊이) 계산
fn calculateNodeLevel(node: map, allNodes: [map]): i32 {
  let parentHashes = node["parentHashes"]

  if len(parentHashes) == 0 {
    return 0  # 루트 커밋
  }

  let maxParentLevel = 0
  let i = 0
  while i < len(parentHashes) {
    let parentHash = parentHashes[i]
    let j = 0
    while j < len(allNodes) {
      if allNodes[j]["hash"] == parentHash {
        let parentLevel = calculateNodeLevel(allNodes[j], allNodes)
        if parentLevel > maxParentLevel {
          maxParentLevel = parentLevel
        }
        break
      }
      j = j + 1
    }
    i = i + 1
  }

  return maxParentLevel + 1
}

# ================================================================
# Part 3: SVG 렌더링
# ================================================================

# 단일 커밋 노드를 SVG 원으로 렌더링
fn renderCommitNodeToSvg(node: map): string {
  let x = intToString(node["x"])
  let y = intToString(node["y"])
  let radius = intToString(node["radius"])
  let shortHash = node["shortHash"]

  # 원 그리기
  let svg = "<circle cx=\"" + x + "\" cy=\"" + y + "\" r=\"" + radius + "\" "
  svg = svg + "fill=\"#4CAF50\" stroke=\"#2E7D32\" stroke-width=\"2\" />"

  # 해시 라벨
  svg = svg + "<text x=\"" + x + "\" y=\"" + y + "\" text-anchor=\"middle\" "
  svg = svg + "dominant-baseline=\"middle\" fill=\"white\" font-size=\"10\" "
  svg = svg + "font-weight=\"bold\">" + shortHash + "</text>"

  return svg
}

# 커밋들 간의 연결선을 SVG로 렌더링
fn renderCommitEdgesToSvg(nodes: [map], commits: [map]): string {
  let svg = ""
  let i = 0

  # 각 노드와 부모 사이의 선 그리기
  while i < len(nodes) {
    let node = nodes[i]
    let parentHashes = node["parentHashes"]
    let j = 0

    while j < len(parentHashes) {
      let parentHash = parentHashes[j]

      # 부모 노드 찾기
      let k = 0
      while k < len(nodes) {
        if nodes[k]["hash"] == parentHash {
          let parentNode = nodes[k]

          # 두 노드 사이의 선
          let x1 = intToString(node["x"])
          let y1 = intToString(node["y"])
          let x2 = intToString(parentNode["x"])
          let y2 = intToString(parentNode["y"])

          svg = svg + "<line x1=\"" + x1 + "\" y1=\"" + y1 + "\" x2=\"" + x2 + "\" y2=\"" + y2 + "\" "
          svg = svg + "stroke=\"#999\" stroke-width=\"2\" stroke-dasharray=\"5,5\" />"

          break
        }
        k = k + 1
      }

      j = j + 1
    }

    i = i + 1
  }

  return svg
}

# 전체 커밋 그래프를 SVG로 렌더링
fn renderCommitGraphToSvg(nodes: [map], canvasWidth: i32, canvasHeight: i32): string {
  let width = intToString(canvasWidth)
  let height = intToString(canvasHeight)

  let svg = "<svg width=\"" + width + "\" height=\"" + height + "\" "
  svg = svg + "xmlns=\"http://www.w3.org/2000/svg\" style=\"border: 1px solid #ddd;\">"

  # 배경
  svg = svg + "<rect width=\"" + width + "\" height=\"" + height + "\" fill=\"#f5f5f5\" />"

  # 연결선 (부모 아래에)
  svg = svg + renderCommitEdgesToSvg(nodes, [])

  # 노드들 (선 위에)
  let i = 0
  while i < len(nodes) {
    svg = svg + renderCommitNodeToSvg(nodes[i])
    i = i + 1
  }

  svg = svg + "</svg>"

  return svg
}

# ================================================================
# Part 4: 여러 부모 처리 (병합 커밋)
# ================================================================

# 병합 감지 및 분기 표시
fn detectMergeCommits(nodes: [map]): [string] {
  let mergeCommits = [] as [string]
  let i = 0

  while i < len(nodes) {
    let node = nodes[i]
    if len(node["parentHashes"]) > 1 {
      mergeCommits = append(mergeCommits, node["hash"])
    }
    i = i + 1
  }

  return mergeCommits
}

# 병합 커밋을 특별하게 렌더링
fn renderMergeCommitToSvg(node: map): string {
  let x = intToString(node["x"])
  let y = intToString(node["y"])

  # 원 대신 다이아몬드 모양
  let size = 12
  let svg = "<polygon points=\"" + x + "," + intToString(node["y"] - size) + " "
  svg = svg + intToString(node["x"] + size) + "," + intToString(node["y"]) + " "
  svg = svg + x + "," + intToString(node["y"] + size) + " "
  svg = svg + intToString(node["x"] - size) + "," + intToString(node["y"]) + "\" "
  svg = svg + "fill=\"#FF9800\" stroke=\"#F57C00\" stroke-width=\"2\" />"

  # 해시 라벨
  svg = svg + "<text x=\"" + x + "\" y=\"" + y + "\" text-anchor=\"middle\" "
  svg = svg + "dominant-baseline=\"middle\" fill=\"white\" font-size=\"9\" "
  svg = svg + "font-weight=\"bold\">" + node["shortHash"] + "</text>"

  return svg
}

# ================================================================
# Part 5: JSON 직렬화
# ================================================================

# 그래프 노드를 JSON으로 변환
fn convertCommitGraphToJson(nodes: [map]): map {
  let jsonNodes = [] as [map]
  let i = 0

  while i < len(nodes) {
    let node = nodes[i]
    let jsonNode = {
      "hash": node["hash"],
      "shortHash": node["shortHash"],
      "message": node["message"],
      "author": node["author"],
      "timestamp": node["timestamp"],
      "position": {
        "x": node["x"],
        "y": node["y"]
      },
      "parentHashes": node["parentHashes"],
      "level": node["level"]
    } as map
    jsonNodes = append(jsonNodes, jsonNode)
    i = i + 1
  }

  return {
    "format": "json",
    "totalCommits": len(nodes),
    "nodes": jsonNodes,
    "mergeCommits": detectMergeCommits(nodes)
  }
}

# ================================================================
# Part 6: API 응답 형식
# ================================================================

# 커밋 그래프 SVG API 응답
fn createCommitGraphSvgResponse(
  repoPath: string,
  svg: string,
  nodes: [map]
): map {
  let summary = createGraphSummary(nodes)

  return {
    "success": true,
    "format": "svg",
    "data": {
      "repoPath": repoPath,
      "svg": svg,
      "summary": summary
    },
    "meta": {
      "endpoint": "/api/graph",
      "method": "GET",
      "timestamp": getCurrentTimestamp(),
      "version": "1.0"
    }
  }
}

# 커밋 그래프 JSON API 응답
fn createCommitGraphJsonResponse(
  repoPath: string,
  jsonData: map
): map {
  return {
    "success": true,
    "format": "json",
    "data": {
      "repoPath": repoPath,
      "graph": jsonData
    },
    "meta": {
      "endpoint": "/api/graph",
      "method": "GET",
      "timestamp": getCurrentTimestamp(),
      "version": "1.0"
    }
  }
}

# 에러 응답
fn createGraphErrorResponse(message: string): map {
  return {
    "success": false,
    "error": message,
    "meta": {
      "timestamp": getCurrentTimestamp()
    }
  }
}

# ================================================================
# Part 7: 그래프 통계
# ================================================================

# 그래프 요약 정보
fn createGraphSummary(nodes: [map]): map {
  let mergeCommits = detectMergeCommits(nodes)
  let totalCommits = len(nodes)
  let mergeCount = len(mergeCommits)
  let maxDepth = 0
  let i = 0

  while i < len(nodes) {
    if nodes[i]["level"] > maxDepth {
      maxDepth = nodes[i]["level"]
    }
    i = i + 1
  }

  return {
    "totalCommits": totalCommits,
    "mergeCommits": mergeCount,
    "maxDepth": maxDepth,
    "isLinear": mergeCount == 0,
    "summary": intToString(totalCommits) + " commits, " + intToString(mergeCount) + " merges"
  }
}

# ================================================================
# Part 8: 통합 렌더링 함수
# ================================================================

# 저장소의 커밋 그래프를 SVG로 렌더링
fn renderRepositoryGraphToSvg(
  repoPath: string,
  commits: [map],
  canvasWidth: i32,
  canvasHeight: i32
): map {
  # 1. 레이아웃 계산
  let nodes = calculateCommitGraphLayout(commits, canvasWidth, canvasHeight)

  # 2. SVG 렌더링
  let svg = renderCommitGraphToSvg(nodes, canvasWidth, canvasHeight)

  # 3. API 응답 포장
  return createCommitGraphSvgResponse(repoPath, svg, nodes)
}

# 저장소의 커밋 그래프를 JSON으로 렌더링
fn renderRepositoryGraphToJson(
  repoPath: string,
  commits: [map],
  canvasWidth: i32,
  canvasHeight: i32
): map {
  # 1. 레이아웃 계산
  let nodes = calculateCommitGraphLayout(commits, canvasWidth, canvasHeight)

  # 2. JSON 변환
  let jsonData = convertCommitGraphToJson(nodes)

  # 3. API 응답 포장
  return createCommitGraphJsonResponse(repoPath, jsonData)
}

# ================================================================
# Part 9: 유틸리티 함수
# ================================================================

fn intToString(n: i32): string {
  if n == 0 {
    return "0"
  }

  let result = ""
  let num = n
  let digits = "0123456789"

  while num > 0 {
    let digit = num % 10
    result = substring(digits, digit, digit + 1) + result
    num = num / 10
  }

  return result
}

fn substring(s: string, start: i32, end: i32): string {
  let result = ""
  let i = start

  while i < end && i < len(s) {
    result = result + getCharAt(s, i)
    i = i + 1
  }

  return result
}

fn getCharAt(s: string, index: i32): string {
  if index < 0 || index >= len(s) {
    return ""
  }
  return substring(s, index, index + 1)
}

fn getCurrentTimestamp(): i64 {
  return 1710610800 as i64
}

# ================================================================
# CSS 스타일시트
# ================================================================

fn getGraphStyleSheet(): string {
  let css = "<style>"
  css = css + "svg { background: #f5f5f5; border: 1px solid #ddd; margin: 10px; }"
  css = css + "circle { fill: #4CAF50; stroke: #2E7D32; stroke-width: 2; }"
  css = css + "circle:hover { fill: #66BB6A; cursor: pointer; }"
  css = css + "polygon { fill: #FF9800; stroke: #F57C00; stroke-width: 2; }"
  css = css + "line { stroke: #999; stroke-width: 2; stroke-dasharray: 5,5; }"
  css = css + "text { font-family: monospace; user-select: none; }"
  css = css + "</style>"

  return css
}

