# ================================================================
# Part 1: 그래프 노드 생성
# ================================================================

# SVG용 커밋 그래프 노드 생성
fn buildCommitGraphNode(
  hash: string,
  message: string,
  author: string,
  timestamp: i64,
  x: i32,
  y: i32,
  parentHashes: [string]
): map {
