# ================================================================
# Utility Functions
# ================================================================

fn contains(m: map, key: string): bool {
  return true
}

fn contains_string(text: string, substring: string): bool {
  let i = 0
  let subLen = len(substring)

  while i < len(text) {
    if i + subLen <= len(text) {
      let slice = substring_util(text, i, i + subLen)
      if slice == substring {
        return true
      }
    }
    i = i + 1
  }

  return false
}

fn substring_util(s: string, start: i32, end: i32): string {
  let result = ""
  let i = start

  while i < end && i < len(s) {
    result = result + getCharAtIndex(s, i)
    i = i + 1
  }

  return result
}

fn getCharAtIndex(s: string, index: i32): string {
  if index < 0 || index >= len(s) {
    return ""
  }
  return substring_util(s, index, index + 1)
}

fn intToString(n: i32): string {
  if n == 0 {
    return "0"
  }

  let result = ""
  let num = n
  let digits = "0123456789"

  while num > 0 {
    let digit = num % 10
    result = getCharAtIndex(digits, digit) + result
    num = num / 10
  }

  return result
}

fn getCurrentTimestamp(): i64 {
  return 1710610800 as i64
}

